;color:#98636a;font-size:10px;letter-spacing:1.6px;font-weight:650}.sv-x{width:30px;height:30px;font-size:24px;border:0;background:#f9eeec;border-radius:50%;line-height:1;color:#70303c}.sv-hero{background:linear-gradient(130deg,#792437,#a54f5d);color:white;min-height:126px;padding:22px 28px;display:flex;align-items:center;gap:17px}.sv-hero .sv-ticket{font-size:36px;color:#ffe4e5}.sv-hero strong{font-size:28px;font-weight:700}.sv-hero p{font-size:12px;margin:3px 0 0;color:#f6dbde}.sv-hero-pill{margin-left:auto;border-radius:50px;background:#ffffff32;font-size:10px;padding:6px 10px;white-space:nowrap}.sv-dialog-body{padding:25px 28px}.sv-dialog-body h2,.sv-form-heading h2{margin:0 0 6px;font-size:18px;color:#37242a;font-weight:650}.sv-muted{color:#887d79;font-size:12px;line-height:1.6;margin:0 0 20px}.sv-detail-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.sv-detail{padding:11px 13px;background:#fdf9f7;border:1px solid #f0e9e6;border-radius:9px;min-width:0}.sv-detail small{display:block;color:#9c918e;font-size:10px;margin-bottom:6px}.sv-detail strong{display:block;font-size:11px;font-weight:550;color:#453735;overflow-wrap:anywhere;line-height:1.5}.sv-terms{margin-top:20px}.sv-terms h3{font-size:13px;margin:0 0 8px;color:#423238}.sv-terms ul{padding-left:20px;font-size:11px;line-height:1.75;color:#786c69;margin:0}.sv-cod{background:#fff7f4;border:1px solid #f3ded7;border-radius:9px;margin-top:18px;padding:13px;display:flex;gap:5px;flex-direction:column;font-size:11px;color:#97616a}.sv-cod strong{font-weight:650;color:#763642}.sv-dialog-actions{border-top:1px solid #f0e7e4;padding:14px 25px;display:flex;gap:10px;justify-content:flex-end}.sv-create-dialog{width:min(780px,100%)}.sv-form-heading{padding:19px 27px 12px}.sv-form-heading p{margin:0;font-size:11px;color:#958783}.sv-form-body{padding:0 27px 20px}.sv-form-section{border-top:1px solid #f1e8e5;padding-top:17px;margin-top:17px}.sv-form-section h3{margin:0 0 15px;font-size:13px;color:#663443;font-weight:650}.sv-form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.sv-field{display:flex;flex-direction:column;gap:6px;font-size:11px;font-weight:550;color:#53454a}.sv-field-label{display:inline-flex;align-items:baseline;justify-content:flex-start;gap:4px;max-width:100%;flex-wrap:wrap;line-height:1.45}.sv-field-label em{display:inline;color:#b9344b;font-style:normal;white-space:nowrap;flex:0 0 auto}.sv-field input,.sv-field select,.sv-field textarea{width:100%;background:#fff;border:1px solid #e3d9d6;border-radius:8px;padding:10px 11px;min-height:39px;outline:0;font-size:11px;color:#393032}.sv-field textarea{resize:vertical}.sv-field :is(input,select,textarea):focus{border-color:#ad6874;box-shadow:0 0 0 3px #ab657011}.sv-field small{color:#a39794;font-size:9.5px;font-weight:400;line-height:1.5}.sv-span2{grid-column:span 2}.sv-error{color:#a22939;background:#fff0f0;border:1px solid #f1d0d3;border-radius:8px;padding:10px;font-size:11px;margin:14px 0}.sv-form-hint{color:#a2938e;font-size:10px;margin-top:20px}.sv-create-dialog .sv-dialog-actions{position:sticky;bottom:0;background:#fff;z-index:1}@media(max-width:1050px){.sv-grid{grid-template-columns:1fr}.sv-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:760px){.sv-page{margin-left:0;padding:100px 13px 25px}.sv-heading{align-items:flex-start;flex-wrap:wrap}.sv-heading h1{font-size:21px}.sv-panel{padding:16px 13px}.sv-panel-head{align-items:flex-start;flex-wrap:wrap}.sv-tools{flex-wrap:wrap}.sv-tools select{flex:1}.sv-dialog-body{padding:18px}.sv-detail-grid,.sv-form-grid{grid-template-columns:1fr}.sv-span2{grid-column:span 1}.sv-form-heading,.sv-form-body{padding-left:16px;padding-right:16px}}@media(max-width:390px){.sv-voucher{grid-template-columns:95px minmax(0,1fr)}.sv-voucher-rail strong{font-size:18px}.sv-voucher-copy{padding:12px 9px}.sv-metrics{gap:8px}.sv-metrics>div{padding:12px}.sv-tabs{gap:9px;padding:0 10px}.sv-tabs button{font-size:11px}}
