];
// Admin eligibility is sample configuration, NOT a verified statement about this seller's catalog.
let shop=[];const apiToken=JSON.parse(document.getElementById('sellerVoucherConfig')?.textContent||'{}').apiToken||'';const apiRequest=async(url,options={})=>{const response=await fetch(url,{...options,headers:{Accept:'application/json','Content-Type':'application/json','X-Requested-With':'XMLHttpRequest',...(apiToken?{Authorization:`Bearer ${apiToken}`}:{})},credentials:'same-origin'});const payload=await response.json().catch(()=>({}));if(!response.ok)throw new Error(Object.values(payload.errors||{}).flat()[0]||payload.message||`Request failed (${response.status})`);return payload};const save=()=>{shop.filter(v=>v.recordId).forEach(v=>apiRequest(`/api/v1/seller/vouchers/${v.recordId}`,{method:'PATCH',body:JSON.stringify({enabled:v.enabled!==false})}).catch(console.error))};const loadVouchers=async()=>{try{const payload=await apiRequest('/api/v1/seller/vouchers');shop=payload.data||[];render()}catch(error){const target=document.getElementById('svShopEmpty');if(target){target.hidden=false;target.textContent=error.message}}};const price=v=>v.discountType==='percent'?`${v.discountValue}%`:money(v.discountValue).replace('.00','');const status=v=>{const now=Date.now();if(v.enabled===false)return 'paused';if((Number(v.claimed)||0)>=Number(v.quantity))return 'exhausted';if(now<new Date(v.starts).getTime())return 'upcoming';if(now>new Date(v.ends).getTime())return 'expired';return 'active'};const label=s=>({active:'Active',upcoming:'Upcoming',expired:'Expired',paused:'Paused',exhausted:'Fully Claimed'})[s]||s;
const display=v=>`<article class="sv-voucher ${v.isAdmin?'admin':''}" role="button" tabindex="0" aria-label="View details for ${esc(v.title)}" data-voucher-card="${esc(v.isAdmin?'admin':'mine')}" data-code="${esc(v.id)}"><div class="sv-voucher-rail"><span class="sv-ticket-icon">▣</span><strong>${esc(price(v))}</strong><small>OFF</small></div><div class="sv-voucher-copy"><div class="sv-voucher-top"><span class="sv-pill ${status(v)}">${label(status(v))}</span><span class="sv-origin">${v.isAdmin?'ShopEase Admin':'Shop Exclusive'}</span></div><h3>${esc(v.title)}</h3><span class="sv-code">${esc(v.id)}</span><p>${esc(v.purpose)}</p><div class="sv-remaining">${Math.max(0,v.quantity-v.claimed)} of ${v.quantity} available · Min. ${money(v.minimumSpend)}</div><div class="sv-voucher-bottom"><span>Valid until ${esc(fmt(v.ends))}</span><span class="sv-inline-actions">${!v.isAdmin?`<button type="button" class="sv-pause-button ${v.enabled===false?'is-paused':''}" data-toggle="${esc(v.id)}" aria-label="${v.enabled===false?'Publish':'Pause'} ${esc(v.title)}">${v.enabled===false?'Publish':'Pause'}</button>`:''}</span></div></div></article>`;
const allAdmin=admin.filter(x=>x.eligible).map(v=>({...v,isAdmin:true,enabled:true}));function render(){const aText=$('svAdminSearch').value.toLowerCase().trim(),aFilter=$('svAdminFilter').value,sText=$('svShopSearch').value.toLowerCase().trim(),sFilter=$('svShopFilter').value;const af=allAdmin.filter(v=>(v.title+' '+v.id).toLowerCase().includes(aText)&&(aFilter==='all'||status(v)===aFilter)),sf=shop.filter(v=>(v.title+' '+v.id).toLowerCase().includes(sText)&&(sFilter==='all'||status(v)===sFilter));$('svAdminGrid').innerHTML=af.map(display).join('');$('svShopGrid').innerHTML=sf.map(display).join('');$('svAdminEmpty').hidden=!!af.length;$('svShopEmpty').hidden=!!sf.length;$('svAdminCount').textContent=allAdmin.length;$('svShopCount').textContent=shop.length;$('svActiveCount').textContent=shop.filter(v=>status(v)==='active').length;$('svAllocationCount').textContent=shop.reduce((s,v)=>s+Number(v.quantity||0),0).toLocaleString('en-PH');$('svAdminTabCount').textContent=`(${allAdmin.length})`;$('svMineTabCount').textContent=`(${shop.length})`}
for(const key of ['svAdminSearch','svShopSearch'])$(key).addEventListener('input',render);for(const key of ['svAdminFilter','svShopFilter'])$(key).addEventListener('change',render);
document.querySelectorAll('[data-tab]').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b===btn));document.querySelectorAll('[data-panel]').forEach(p=>p.hidden=p.dataset.panel!==btn.dataset.tab)}));
let lastFocus=null;const open=overlay=>{lastFocus=document.activeElement;overlay.hidden=false;overlay.setAttribute('aria-hidden','false');document.body.style.overflow='hidden';overlay.querySelector('.sv-x')?.focus()},close=overlay=>{overlay.hidden=true;overlay.setAttribute('aria-hidden','true');document.body.style.overflow='';lastFocus?.focus()};document.querySelectorAll('.sv-overlay').forEach(overlay=>{overlay.addEventListener('click',e=>{if(e.target===overlay||e.target.closest('[data-close]'))close(overlay)})});document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelectorAll('.sv-overlay:not([hidden])').forEach(close)});
function details(v){$('svDetailsTitle').textContent=v.title;$('svDetailsValue').textContent=`${price(v)} OFF`;$('svDetailsSubtitle').textContent=v.isAdmin?'Platform-issued eligible voucher':'Exclusive voucher for this seller';$('svDetailsStatus').textContent=label(status(v));$('svDetailsPurpose').textContent=v.purpose||'Discount available on eligible items.';const fields=[['Voucher Code',v.id],['Discount Value',`${price(v)} OFF`],['Minimum Spend',money(v.minimumSpend)],['Maximum Discount',money(v.maximumDiscount)],['Valid From',fmt(v.starts)],['Expires',fmt(v.ends)],['Eligible Items',v.eligibleItems],['Eligible Buyers',v.eligibleBuyers],['Total Allocation',`${v.quantity} voucher${v.quantity===1?'':'s'}`],['Already Claimed',v.claimed||0],['Available Allocation',Math.max(0,v.quantity-v.claimed)],['Uses Per Buyer',v.perBuyer],['Voucher Stacking',v.stacking],['Participating Shops',v.scope||'This shop only'],['Payment Method','Cash on Delivery (COD)'],['Current Status',label(status(v))]];$('svDetailsGrid').innerHTML=fields.map(([l,val])=>`<div class="sv-detail"><small>${esc(l)}</small><strong>${esc(val)}</strong></div>`).join('');$('svDetailsTerms').innerHTML=[v.terms||'Voucher applies only to qualifying item subtotal.', 'Voucher must be active and within its date/time window at checkout.','First-come-first-served: valid use requires remaining allocation and compliance with each buyer limit.','Cannot be exchanged for cash; not retroactively applicable to previous orders.'].map(x=>`<li>${esc(x)}</li>`).join('');const toggle=$('svDetailsToggle');toggle.hidden=!!v.isAdmin;if(!v.isAdmin){toggle.textContent=v.enabled===false?'Publish Voucher':'Pause Voucher';toggle.onclick=()=>{v.enabled=v.enabled===false;save();render();close($('svDetailsOverlay'))}}open($('svDetailsOverlay'))}
document.addEventListener('click',e=>{const toggle=e.target.closest('[data-toggle]');if(toggle){e.stopPropagation();const v=shop.find(x=>x.id===toggle.dataset.toggle);if(v){v.enabled=v.enabled===false;save();render()}return}const card=e.target.closest('[data-voucher-card]');if(card){const v=(card.dataset.voucherCard==='admin'?allAdmin:shop).find(x=>x.id===card.dataset.code);if(v)details(v)}});
document.addEventListener('keydown',e=>{if(e.target.matches('[data-voucher-card]')&&(e.key==='Enter'||e.key===' ')){e.preventDefault();const card=e.target;const v=(card.dataset.voucherCard==='admin'?allAdmin:shop).find(x=>x.id===card.dataset.code);if(v)details(v)}});
const createOverlay=$('svCreateOverlay'),form=$('svVoucherForm'),ferr=$('svFormError');function launchCreate(){form.reset();ferr.hidden=true;$('svProductField').hidden=true;const today=new Date(),offset=today.getTimezoneOffset()*60000,local=new Date(today.getTime()+60000-offset).toISOString().slice(0,16);form.elements.starts.value=local;const later=new Date(today.getTime()+30*86400000);form.elements.ends.value=new Date(later.getTime()-offset).toISOString().slice(0,16);open(createOverlay)}$('svCreate')?.addEventListener('click',launchCreate);$('svCreateSecondary').addEventListener('click',launchCreate);$('svEligibleItems').addEventListener('change',e=>{$('svProductField').hidden=e.target.value!=='selected'});form.elements.code.addEventListener('input',e=>{e.target.value=e.target.value.toUpperCase().replace(/[^A-Z0-9_-]/g,'')});
form.addEventListener('submit',async e=>{e.preventDefault();ferr.hidden=true;const d=Object.fromEntries(new FormData(form));const err=message=>{ferr.textContent=message;ferr.hidden=false;ferr.scrollIntoView({behavior:'smooth',block:'nearest'})};if(!form.checkValidity()){form.reportValidity();return err('Please complete all required fields and use valid positive numbers.')}const code=d.code.trim().toUpperCase(),dv=Number(d.discountValue),ms=Number(d.minimumSpend),cap=Number(d.maximumDiscount),qty=Number(d.quantity),per=Number(d.perBuyer);if(!/^[A-Z0-9_-]{4,20}$/.test(code))return err('Use a 4–20 character code with letters, numbers, hyphens or underscores.');if([...shop,...admin].some(x=>x.id.toUpperCase()===code))return err('This voucher code already exists. Choose a unique code.');if(!(dv>0)||!Number.isFinite(dv)||!(cap>0)||!(ms>=0))return err('Discount value and maximum discount must be greater than zero; minimum spend cannot be negative.');if(d.discountType==='percent'&&dv>100)return err('Percentage discount cannot exceed 100%.');if(d.discountType==='fixed'&&cap<dv)return err('Maximum discount cannot be below the fixed discount amount.');if(!Number.isInteger(qty)||qty<1||!Number.isInteger(per)||per<1)return err('Total vouchers and per-buyer uses must be whole numbers greater than zero.');if(per>qty)return err('Per-buyer uses cannot exceed the total voucher allocation.');if(d.eligibleItems==='selected'&&!d.productIds.trim())return err('Enter at least one product SKU or ID for selected products.');const start=new Date(d.starts),end=new Date(d.ends);if(!Number.isFinite(start.getTime())||!Number.isFinite(end.getTime())||end<=start)return err('End date/time must be later than start date/time.');if(end.getTime()<=Date.now())return err('Voucher end date/time must be in the future.');const itemText=d.eligibleItems==='all'?'All products in my shop':`Selected shop products: ${d.productIds.split(',').map(x=>x.trim()).filter(Boolean).join(', ')}`;const buyerText=({all:'All buyers',first:'First-time buyers at my shop',returning:'Returning buyers'})[d.eligibleBuyers];const stackingText=d.stacking==='shipping'?'Can combine with shipping voucher only':'Cannot combine with other vouchers';let payload;try{payload=await apiRequest('/api/v1/seller/vouchers',{method:'POST',body:JSON.stringify({title:d.title.trim(),code,discountType:d.discountType,discountValue:dv,minimumSpend:ms,maximumDiscount:cap,eligibleItems:d.eligibleItems,productIds:d.productIds,eligibleBuyers:d.eligibleBuyers,stacking:d.stacking,quantity:qty,perBuyer:per,starts:d.starts,ends:d.ends,terms:d.terms.trim(),enabled:d.enabled==='true'})})}catch(error){return err(error.message)}shop.unshift(payload.data);render();close(createOverlay);document.querySelector('[data-tab="mine"]').click();$('svShopSearch').value='';$('svShopFilter').value='all';render();details(shop[0])});render();loadVouchers();
});
</script></body></html>
